          </div>
        )}

        {/* Specialized estimator panels per (sign_type × action) */}
        {isMonumentRepaint && (
          <RepaintMonumentPanel item={item} settings={settings} onChange={update} />
        )}
      </CardContent>
    </Card>
  );
}

